import{_ as a,o as t,c as o,ae as s}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Upgrading","description":"Upgrade Better Laravel from v2 to v4. Version 3 was skipped; the base classes, commands and config keys are unchanged.","frontmatter":{"title":"Upgrading","description":"Upgrade Better Laravel from v2 to v4. Version 3 was skipped; the base classes, commands and config keys are unchanged."},"headers":[],"relativePath":"better-laravel/upgrading.md","filePath":"better-laravel/upgrading.md"}'),r={name:"better-laravel/upgrading.md"};function i(d,e,n,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="upgrading-to-v4" tabindex="-1">Upgrading to v4 <a class="header-anchor" href="#upgrading-to-v4" aria-label="Permalink to &quot;Upgrading to v4&quot;">​</a></h1><p>v4 follows v2.0.0 directly. Version 3 was skipped so that every Laranex package shares the same major version. The base classes (<code>Cores\\Controller</code>, <code>Feature</code>, <code>Operation</code>, <code>Job</code>, <code>QueueableJob</code>, <code>Request</code>), the <code>serve()</code>, <code>run()</code> and <code>runInQueue()</code> methods, the command signatures, the config keys and the generated file locations are the same as in v2.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>PHP 8.1+ (the floor was 8.2 in v2) and Laravel 10 to 13.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/better-laravel:^4.0</span></span></code></pre></div><p>The package no longer depends on <code>spatie/laravel-package-tools</code>; it requires <code>laravel/framework</code> (10 through 13), since it builds on framework-only classes such as <code>FormRequest</code>, <code>DispatchesJobs</code> and <code>ValidatesRequests</code>. If your application relied on the package to pull in <code>spatie/laravel-package-tools</code>, require it yourself.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>The <code>better:*</code> commands now exit with code <code>1</code> when generation fails (for example when the file exists and <code>--force</code> was not given). In v2 they always returned <code>0</code>. Update scripts or CI steps that check the exit code.</p><p>Names containing <code>/</code> or <code>\\</code> (for example <code>better:feature Blog/CreatePost Blog</code>) are now rejected with an error and exit code <code>1</code>; v2 wrote a file whose class name contained the slash.</p><h2 id="stubs" tabindex="-1">Stubs <a class="header-anchor" href="#stubs" aria-label="Permalink to &quot;Stubs&quot;">​</a></h2><p>The queueable job stub declared <code>__construct(): void</code>, a fatal error in every job generated with <code>--queue</code>. If you published the stubs, republish them to pick up the fix:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;better-laravel-stubs&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>Republishing also brings the other stub changes: generated route files import the <code>Route</code> facade and use a prefix without a leading slash (<code>&#39;prefix&#39; =&gt; &#39;v1/blogs&#39;</code>), the feature stub&#39;s <code>handle</code> method declares a <code>mixed</code> return type instead of <code>int</code> and returns <code>null</code> until you fill it in (a feature generated from the old stub threw a <code>TypeError</code> when served unchanged), and the request stub documents its <code>rules()</code> return type. Fix any job already generated from the old queueable stub by removing <code>: void</code> from its constructor.</p><h2 id="publish-tags" tabindex="-1">Publish tags <a class="header-anchor" href="#publish-tags" aria-label="Permalink to &quot;Publish tags&quot;">​</a></h2><p>The tags <code>better-laravel-config</code>, <code>better-laravel-views</code> and <code>better-laravel-stubs</code> are unchanged. A new <code>better-laravel</code> tag publishes all three at once.</p><h2 id="route-registration" tabindex="-1">Route registration <a class="header-anchor" href="#route-registration" aria-label="Permalink to &quot;Route registration&quot;">​</a></h2><p>Route files under <code>routes/web</code> and <code>routes/api</code> are now registered during the service provider&#39;s <code>boot()</code> method instead of <code>register()</code>, so host configuration (including cached config) is honored. Files are loaded in sorted order. Routes are still skipped when the route cache is in use.</p><h2 id="extending-the-package" tabindex="-1">Extending the package <a class="header-anchor" href="#extending-the-package" aria-label="Permalink to &quot;Extending the package&quot;">​</a></h2><ul><li><code>Commands\\BaseCommand</code> is now abstract. Extend it from a concrete command instead of instantiating it.</li><li><code>Laranex\\BetterLaravel\\Str</code> no longer overrides <code>studly()</code>; the Laravel method is inherited. If you called <code>Str::studly()</code> with a second argument, pass only the value. All other <code>Str</code> helpers take <code>string</code> parameters.</li><li><code>Bus\\UnitDispatcher::runInQueue()</code> now declares a <code>Illuminate\\Foundation\\Bus\\PendingDispatch</code> return type.</li><li><code>JobGenerator::getStubContents()</code> defaults to the synchronous job stub when called without arguments.</li><li><code>BetterLaravel::getAllFilesOfADirectory()</code> returns the files sorted.</li><li>Every source file declares <code>strict_types=1</code>.</li></ul>',19)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
